<script setup>
import { SHOPPING_OPERATION_PAGE_EVENTS, SHOPPING_OPERATION_PAGE_PROPS, localizeOperationPage } from './shopping-operation-page-contract'
const props=defineProps(SHOPPING_OPERATION_PAGE_PROPS); const emit=defineEmits(SHOPPING_OPERATION_PAGE_EVENTS); const l=(zh,en)=>localizeOperationPage(props.languageBase,zh,en)
</script>
<template>
<main class="tr-ops" :data-page="pageKey" data-testid="shopping-store-operation-page"><header class="tr-opbar"><button @click="emit('back')">←</button><strong>TRADERS <small>WHOLESALE CLUB</small></strong><div><button data-testid="shopping-open-service" @click="emit('open-service')">MEMBER</button><button @click="emit('open-orders')">PICKUPS</button><button @click="emit('open-cart')"><i class="fas fa-cart-flatbed"></i><b v-if="cartQuantity">{{ cartQuantity }}</b></button></div></header>
